using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Square.Core.Models;
using Square.Models.Enums;

namespace Square.Models;

/// <summary>
/// Represents a change in state or quantity of product inventory at a
/// particular time and location.
/// </summary>
public record InventoryAdjustment
{
    /// <summary>
    /// A unique ID generated by Square for the
    /// <c>InventoryAdjustment</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("id")]
    [MaxLength(100)]
    public string? Id { get; init; }

    /// <summary>
    /// An optional ID provided by the application to tie the
    /// <c>InventoryAdjustment</c> to an external
    /// system.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("reference_id")]
    [MaxLength(255)]
    public string? ReferenceId { get; init; }

    /// <summary>
    /// Indicates the state of a tracked item quantity in the lifecycle of goods.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("from_state")]
    public InventoryState? FromState { get; init; }

    /// <summary>
    /// Indicates the state of a tracked item quantity in the lifecycle of goods.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("to_state")]
    public InventoryState? ToState { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:Location">Location</see> where the related
    /// quantity of items is being tracked before the adjustment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("from_location_id")]
    [MaxLength(100)]
    public string? FromLocationId { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:Location">Location</see> where the related
    /// quantity of items is being tracked after the adjustment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("to_location_id")]
    [MaxLength(100)]
    public string? ToLocationId { get; init; }

    /// <summary>
    /// The Square-generated ID of the
    /// <see href="entity:CatalogObject">CatalogObject</see> being tracked.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("catalog_object_id")]
    [MaxLength(100)]
    public string? CatalogObjectId { get; init; }

    /// <summary>
    /// The <see href="entity:CatalogObjectType">type</see> of the <see href="entity:CatalogObject">CatalogObject</see> being tracked.
    /// <para>
    /// The Inventory API supports setting and reading the <c>"catalog_object_type": "ITEM_VARIATION"</c> field value.
    /// In addition, it can also read the <c>"catalog_object_type": "ITEM"</c> field value that is set by the Square Restaurants app.
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("catalog_object_type")]
    [MaxLength(14)]
    public string? CatalogObjectType { get; init; }

    /// <summary>
    /// The number of items affected by the adjustment as a decimal string.
    /// Can support up to 5 digits after the decimal point.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("quantity")]
    [MaxLength(26)]
    public string? Quantity { get; init; }

    /// <summary>
    /// Represents an amount of money. <c>Money</c> fields can be signed or unsigned.
    /// Fields that do not explicitly define whether they are signed or unsigned are
    /// considered unsigned and can only hold positive amounts. For signed fields, the
    /// sign of the value indicates the purpose of the money transfer. See
    /// <see href="https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts">Working with Monetary Amounts</see>
    /// for more information.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("total_price_money")]
    public Money? TotalPriceMoney { get; init; }

    /// <summary>
    /// A client-generated RFC 3339-formatted timestamp that indicates when
    /// the inventory adjustment took place. For inventory adjustment updates, the <c>occurred_at</c>
    /// timestamp cannot be older than 24 hours or in the future relative to the
    /// time of the request.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("occurred_at")]
    [MaxLength(34)]
    public string? OccurredAt { get; init; }

    /// <summary>
    /// An RFC 3339-formatted timestamp that indicates when the inventory adjustment is received.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("created_at")]
    [MaxLength(34)]
    public string? CreatedAt { get; init; }

    /// <summary>
    /// Represents information about the application used to generate a change.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("source")]
    public SourceApplication? Source { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:Employee">Employee</see> responsible for the
    /// inventory adjustment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("employee_id")]
    [MaxLength(100)]
    public string? EmployeeId { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:TeamMember">Team Member</see> responsible for the
    /// inventory adjustment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("team_member_id")]
    [MaxLength(100)]
    public string? TeamMemberId { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:Transaction">Transaction</see> that
    /// caused the adjustment. Only relevant for payment-related state
    /// transitions.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("transaction_id")]
    [MaxLength(255)]
    public string? TransactionId { get; init; }

    /// <summary>
    /// The Square-generated ID of the <see href="entity:Refund">Refund</see> that
    /// caused the adjustment. Only relevant for refund-related state
    /// transitions.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("refund_id")]
    [MaxLength(255)]
    public string? RefundId { get; init; }

    /// <summary>
    /// The Square-generated ID of the purchase order that caused the
    /// adjustment. Only relevant for state transitions from the Square for Retail
    /// app.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("purchase_order_id")]
    [MaxLength(100)]
    public string? PurchaseOrderId { get; init; }

    /// <summary>
    /// The Square-generated ID of the goods receipt that caused the
    /// adjustment. Only relevant for state transitions from the Square for Retail
    /// app.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("goods_receipt_id")]
    [MaxLength(100)]
    public string? GoodsReceiptId { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("adjustment_group")]
    public InventoryAdjustmentGroup? AdjustmentGroup { get; init; }

    /// <summary>
    /// Represents an amount of money. <c>Money</c> fields can be signed or unsigned.
    /// Fields that do not explicitly define whether they are signed or unsigned are
    /// considered unsigned and can only hold positive amounts. For signed fields, the
    /// sign of the value indicates the purpose of the money transfer. See
    /// <see href="https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts">Working with Monetary Amounts</see>
    /// for more information.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cost_money")]
    public Money? CostMoney { get; init; }

    /// <summary>
    /// The Square-generated ID of the Vendor from which the merchant purchased this product.
    /// This field is only applicable for stock receive adjustments that introduce stock into the system (from_state is NONE or UNLINKED_RETURN).
    /// This field will only accept writes if the merchant has an active subscription for either Retail Plus, Restaurants Plus, or Restaurants Premium.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("vendor_id")]
    [MaxLength(100)]
    public string? VendorId { get; init; }

    /// <summary>
    /// The Square-generated ID of the InventoryPhysicalCount (recount) that generated this adjustment, if applicable.
    /// The quantity of an adjustment generated by a physical count cannot be edited.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("physical_count_id")]
    public string? PhysicalCountId { get; init; }

    /// <summary>
    /// Identifies a standard or custom inventory adjustment reason.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("reason_id")]
    public InventoryAdjustmentReasonId? ReasonId { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
